// ---------------------------------------------------- bitwise / logical (P1)
// Bitwise &,|,^ require an integral dtype (bool counts). We guard with
// `if constexpr` so the template is well-formed for T=double (the discarded
// branch is never instantiated, so `a & b` never fails to compile on doubles).
enum class BitOp { And, Or, Xor };

template <class T>
inline T apply_bitop(BitOp op, T a, T b) {
    if constexpr (std::is_integral<T>::value) {
        switch (op) {
            case BitOp::And: return (T)(a & b);
            case BitOp::Or:  return (T)(a | b);
            case BitOp::Xor: return (T)(a ^ b);
        }
    } else {
        throw std::runtime_error("nd: bitwise op requires an integral dtype");
    }
    return T{};
}

template <class T>
inline Array<T> bitwise(const Array<T>& a, const Array<T>& b, BitOp op) {
    if constexpr (std::is_integral<T>::value) {   // bool counts as integral
        switch (op) {
            case BitOp::And: return ew_binary<T,T>(a, b, [](T x, T y){ return (T)(x & y); });
            case BitOp::Or:  return ew_binary<T,T>(a, b, [](T x, T y){ return (T)(x | y); });
            case BitOp::Xor: return ew_binary<T,T>(a, b, [](T x, T y){ return (T)(x ^ y); });
        }
        return ew_binary<T,T>(a, b, [](T x, T y){ return (T)(x & y); });
    } else {
        throw std::runtime_error("nd: bitwise op requires an integral dtype");
    }
}

template <class T> inline Array<T> bit_and(const Array<T>& a, const Array<T>& b){ return bitwise(a,b,BitOp::And); }
template <class T> inline Array<T> bit_or (const Array<T>& a, const Array<T>& b){ return bitwise(a,b,BitOp::Or ); }
template <class T> inline Array<T> bit_xor(const Array<T>& a, const Array<T>& b){ return bitwise(a,b,BitOp::Xor); }
template <class T> inline Array<T> bit_and(const Array<T>& a, T s){ return bitwise(a,scalar<T>(s),BitOp::And); }
template <class T> inline Array<T> bit_and(T s, const Array<T>& a){ return bitwise(scalar<T>(s),a,BitOp::And); }
template <class T> inline Array<T> bit_or (const Array<T>& a, T s){ return bitwise(a,scalar<T>(s),BitOp::Or ); }
template <class T> inline Array<T> bit_or (T s, const Array<T>& a){ return bitwise(scalar<T>(s),a,BitOp::Or ); }
template <class T> inline Array<T> bit_xor(const Array<T>& a, T s){ return bitwise(a,scalar<T>(s),BitOp::Xor); }
template <class T> inline Array<T> bit_xor(T s, const Array<T>& a){ return bitwise(scalar<T>(s),a,BitOp::Xor); }

// ~a : numpy inverts bool->logical-not, integer->(-x-1).
template <class T>
inline Array<T> invert(const Array<T>& a) {
    Array<T> c = a.copy();
    int64_t n = c.size();
    if constexpr (std::is_same<T, bool>::value) {
        for (int64_t i = 0; i < n; ++i) (*c.data)[(size_t)i] = !(bool)(*c.data)[(size_t)i];
    } else if constexpr (std::is_integral<T>::value) {
        for (int64_t i = 0; i < n; ++i) (*c.data)[(size_t)i] = (T)(~(*c.data)[(size_t)i]);
    } else {
        throw std::runtime_error("nd: ~ requires an integral dtype");
    }
    return c;
}

// np.logical_and/or/not: always return bool regardless of operand dtype.
template <class T>
inline Array<bool> logical_and(const Array<T>& a, const Array<T>& b) {
    return ew_binary<bool,T>(a, b, [](T x, T y){ return (x != (T)0) && (y != (T)0); });
}
template <class T>
inline Array<bool> logical_or(const Array<T>& a, const Array<T>& b) {
    return ew_binary<bool,T>(a, b, [](T x, T y){ return (x != (T)0) || (y != (T)0); });
}
template <class T>
inline Array<bool> logical_not(const Array<T>& a) {
    Array<T> c = a.is_contiguous() ? a : a.copy();
    Array<bool> out = Array<bool>::alloc(a.shape);
    int64_t n = out.size();
    for (int64_t i = 0; i < n; ++i) (*out.data)[(size_t)i] = ((T)(*c.data)[(size_t)(c.offset+i)] == (T)0);
    return out;
}

// -------------------------------------------------------------- where (select)
// np.where(cond, a, b): elementwise select with full 3-way broadcast.
template <class T>
inline Array<T> where(const Array<bool>& cond, const Array<T>& a, const Array<T>& b) {
    Shape s1 = broadcast_shapes(cond.shape, a.shape);
    Shape osh = broadcast_shapes(s1, b.shape);
    Array<T> out = Array<T>::alloc(osh);
    auto& CV = *cond.data; auto& AV = *a.data; auto& BV = *b.data; auto& OV = *out.data;
    if (osh.empty()) {  // 0-d result
        OV[0] = (bool)CV[(size_t)cond.offset] ? (T)AV[(size_t)a.offset] : (T)BV[(size_t)b.offset];
        return out;
    }
    // cond is always bool (bit-packed vector<bool>), so proxy-index throughout;
    // still incremental over the outer axes (no per-element N-d offset recompute).
    Shape sc = bcast_strides(cond, osh), sa = bcast_strides(a, osh),
          sb = bcast_strides(b, osh), so = c_strides(osh);
    int64_t inner = osh.back();
    int64_t ic = sc.back(), ia = sa.back(), ib = sb.back();
    Shape outer(osh.begin(), osh.end() - 1);
    Shape oc(sc.begin(), sc.end() - 1), oa(sa.begin(), sa.end() - 1),
          ob(sb.begin(), sb.end() - 1), oo(so.begin(), so.end() - 1);
    std::vector<int64_t> bases = {cond.offset, a.offset, b.offset, 0};
    std::vector<const int64_t*> ostr = {oc.data(), oa.data(), ob.data(), oo.data()};
    ew_outer(outer, bases, ostr, [&]() {
        int64_t bc = bases[0], ba = bases[1], bb = bases[2], bo = bases[3];
        for (int64_t i = 0; i < inner; ++i)
            OV[(size_t)(bo + i)] = (bool)CV[(size_t)(bc + i*ic)]
                ? (T)AV[(size_t)(ba + i*ia)] : (T)BV[(size_t)(bb + i*ib)];
    });
    return out;
}
template <class T> inline Array<T> where(const Array<bool>& c, T a, const Array<T>& b){ return where(c, scalar<T>(a), b); }
template <class T> inline Array<T> where(const Array<bool>& c, const Array<T>& a, T b){ return where(c, a, scalar<T>(b)); }
template <class T> inline Array<T> where(const Array<bool>& c, T a, T b){ return where(c, scalar<T>(a), scalar<T>(b)); }

// ---------------------------------------------------------------- ufuncs (1)
template <class T, class F>
inline Array<double> apply1(const Array<T>& a, F f) {
    Array<T> c = a.is_contiguous() ? a : a.copy();
    Array<double> out = Array<double>::alloc(a.shape);
    int64_t n = out.size();
    for (int64_t i = 0; i < n; ++i)
        (*out.data)[(size_t)i] = f((double)(*c.data)[(size_t)(c.offset + i)]);
    return out;
}

template <class T> inline Array<double> sin(const Array<T>& a){ return apply1(a,[](double x){return std::sin(x);}); }
template <class T> inline Array<double> cos(const Array<T>& a){ return apply1(a,[](double x){return std::cos(x);}); }
template <class T> inline Array<double> tan(const Array<T>& a){ return apply1(a,[](double x){return std::tan(x);}); }
template <class T> inline Array<double> asin(const Array<T>& a){ return apply1(a,[](double x){return std::asin(x);}); }
template <class T> inline Array<double> acos(const Array<T>& a){ return apply1(a,[](double x){return std::acos(x);}); }
template <class T> inline Array<double> atan(const Array<T>& a){ return apply1(a,[](double x){return std::atan(x);}); }
template <class T> inline Array<double> exp(const Array<T>& a){ return apply1(a,[](double x){return std::exp(x);}); }
template <class T> inline Array<double> log(const Array<T>& a){ return apply1(a,[](double x){return std::log(x);}); }
template <class T> inline Array<double> sqrt(const Array<T>& a){ return apply1(a,[](double x){return std::sqrt(x);}); }
template <class T> inline Array<double> fabs(const Array<T>& a){ return apply1(a,[](double x){return std::fabs(x);}); }
template <class T> inline Array<double> floor(const Array<T>& a){ return apply1(a,[](double x){return std::floor(x);}); }
