class SpineBuildSystemCmd : public MPxCommand {
public:
    static void* creator() { return new SpineBuildSystemCmd(); }
    static MSyntax newSyntax() {
        MSyntax syn;
        syn.addFlag("-t", "-transforms", MSyntax::kString);
        syn.makeFlagMultiUse("-t");
        syn.addFlag("-n", "-n_flag", MSyntax::kLong);
        syn.addFlag("-d", "-degree", MSyntax::kLong);
        syn.addFlag("-s", "-samples", MSyntax::kDouble);
        syn.makeFlagMultiUse("-s");
        syn.addFlag("-aa", "-aim_axis", MSyntax::kLong);
        syn.addFlag("-ua", "-up_axis", MSyntax::kLong);
        syn.addFlag("-rt", "-rider_type", MSyntax::kString);
        syn.addFlag("-rp", "-rider_prefix", MSyntax::kString);
        syn.addFlag("-p", "-periodic", MSyntax::kBoolean);
        syn.addFlag("-r", "-rotate", MSyntax::kString);
        syn.addFlag("-sc", "-scale", MSyntax::kString);
        syn.addFlag("-rc", "-rotate_controls", MSyntax::kString);
        syn.makeFlagMultiUse("-rc");
        syn.addFlag("-sca", "-scale_controls", MSyntax::kString);
        syn.makeFlagMultiUse("-sca");
        syn.addFlag("-rm", "-rotate_matrix", MSyntax::kString);
        syn.addFlag("-sm", "-scale_matrix", MSyntax::kString);
        syn.addFlag("-u", "-up_axes", MSyntax::kLong);
        syn.makeFlagMultiUse("-u");
        syn.addFlag("-ro", "-rotate_projection", MSyntax::kString);
        syn.addFlag("-sp", "-scale_projection", MSyntax::kString);
        syn.addFlag("-tp", "-translate_projection", MSyntax::kString);
        syn.addFlag("-dc", "-display_curve", MSyntax::kBoolean);
        // kSelectionList (not kStringObjects) to match getObjects(MSelectionList&)
        // and the shipped setMeshRegion contract; useSelectionAsDefault then
        // fills the target from the active selection when none is named.
        //
        // The object MAX is per-command (1): an instance command operates
        // on ONE node, but a create command is the blendShape/skinCluster shape
        // -- its free objects are the geometry the new node is applied to, and
        // there can be many. Widening it for every command would stop Maya
        // rejecting a second object on an instance command, so it is not.
        syn.setObjectType(MSyntax::kSelectionList, 0, 1);
        syn.useSelectionAsDefault(true);
        return syn;
    }
    MStatus doIt(const MArgList& argList) override {
        MStatus st;
        MArgDatabase argData(syntax(), argList, &st);
        if (!st) return st;
        std::string blob;
        if (argData.isFlagSet("-t")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "transforms"; blob += "\x1f"; blob += "list:str"; blob += "\x1f";
            unsigned _n = argData.numberOfFlagUses("-t");
            for (unsigned _i = 0; _i < _n; ++_i) {
                MArgList _al;
                if (argData.getFlagArgumentList("-t", _i, _al) != MS::kSuccess) continue;
                if (_i) blob += "\x1e";
                blob += _str(_al.asString(0));
            }
        }
        if (argData.isFlagSet("-n")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "n"; blob += "\x1f"; blob += "int"; blob += "\x1f";
            int _vn{};
            argData.getFlagArgument("-n", 0, _vn);
            blob += _str(_vn);
        }
        if (argData.isFlagSet("-d")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "degree"; blob += "\x1f"; blob += "int"; blob += "\x1f";
            int _vd{};
            argData.getFlagArgument("-d", 0, _vd);
            blob += _str(_vd);
        }
        if (argData.isFlagSet("-s")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "samples"; blob += "\x1f"; blob += "list:float"; blob += "\x1f";
            unsigned _n = argData.numberOfFlagUses("-s");
            for (unsigned _i = 0; _i < _n; ++_i) {
                MArgList _al;
                if (argData.getFlagArgumentList("-s", _i, _al) != MS::kSuccess) continue;
                if (_i) blob += "\x1e";
                blob += _str(_al.asDouble(0));
            }
        }
        if (argData.isFlagSet("-aa")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "aim_axis"; blob += "\x1f"; blob += "int"; blob += "\x1f";
            int _vaa{};
            argData.getFlagArgument("-aa", 0, _vaa);
            blob += _str(_vaa);
        }
        if (argData.isFlagSet("-ua")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "up_axis"; blob += "\x1f"; blob += "int"; blob += "\x1f";
            int _vua{};
            argData.getFlagArgument("-ua", 0, _vua);
            blob += _str(_vua);
        }
        if (argData.isFlagSet("-rt")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "rider_type"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vrt{};
            argData.getFlagArgument("-rt", 0, _vrt);
            blob += _str(_vrt);
        }
        if (argData.isFlagSet("-rp")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "rider_prefix"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vrp{};
            argData.getFlagArgument("-rp", 0, _vrp);
            blob += _str(_vrp);
        }
        if (argData.isFlagSet("-p")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "periodic"; blob += "\x1f"; blob += "bool"; blob += "\x1f";
            bool _vp{};
            argData.getFlagArgument("-p", 0, _vp);
            blob += _str(_vp);
        }
        if (argData.isFlagSet("-r")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "rotate"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vr{};
            argData.getFlagArgument("-r", 0, _vr);
            blob += _str(_vr);
        }
        if (argData.isFlagSet("-sc")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "scale"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vsc{};
            argData.getFlagArgument("-sc", 0, _vsc);
            blob += _str(_vsc);
        }
        if (argData.isFlagSet("-rc")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "rotate_controls"; blob += "\x1f"; blob += "list:str"; blob += "\x1f";
            unsigned _n = argData.numberOfFlagUses("-rc");
            for (unsigned _i = 0; _i < _n; ++_i) {
                MArgList _al;
                if (argData.getFlagArgumentList("-rc", _i, _al) != MS::kSuccess) continue;
                if (_i) blob += "\x1e";
                blob += _str(_al.asString(0));
            }
        }
        if (argData.isFlagSet("-sca")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "scale_controls"; blob += "\x1f"; blob += "list:str"; blob += "\x1f";
            unsigned _n = argData.numberOfFlagUses("-sca");
            for (unsigned _i = 0; _i < _n; ++_i) {
                MArgList _al;
                if (argData.getFlagArgumentList("-sca", _i, _al) != MS::kSuccess) continue;
                if (_i) blob += "\x1e";
                blob += _str(_al.asString(0));
            }
        }
        if (argData.isFlagSet("-rm")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "rotate_matrix"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vrm{};
            argData.getFlagArgument("-rm", 0, _vrm);
            blob += _str(_vrm);
        }
        if (argData.isFlagSet("-sm")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "scale_matrix"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vsm{};
            argData.getFlagArgument("-sm", 0, _vsm);
            blob += _str(_vsm);
        }
        if (argData.isFlagSet("-u")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "up_axes"; blob += "\x1f"; blob += "list:int"; blob += "\x1f";
            unsigned _n = argData.numberOfFlagUses("-u");
            for (unsigned _i = 0; _i < _n; ++_i) {
                MArgList _al;
                if (argData.getFlagArgumentList("-u", _i, _al) != MS::kSuccess) continue;
                if (_i) blob += "\x1e";
                blob += _str(_al.asInt(0));
            }
        }
        if (argData.isFlagSet("-ro")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "rotate_projection"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vro{};
            argData.getFlagArgument("-ro", 0, _vro);
            blob += _str(_vro);
        }
        if (argData.isFlagSet("-sp")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "scale_projection"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vsp{};
            argData.getFlagArgument("-sp", 0, _vsp);
            blob += _str(_vsp);
        }
        if (argData.isFlagSet("-tp")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "translate_projection"; blob += "\x1f"; blob += "str"; blob += "\x1f";
            MString _vtp{};
            argData.getFlagArgument("-tp", 0, _vtp);
            blob += _str(_vtp);
        }
        if (argData.isFlagSet("-dc")) {
            if (!blob.empty()) blob += "\x1d";
            blob += "display_curve"; blob += "\x1f"; blob += "bool"; blob += "\x1f";
            bool _vdc{};
            argData.getFlagArgument("-dc", 0, _vdc);
            blob += _str(_vdc);
        }
        // ALL object names, RS-joined. Reading them here -- inside doIt, before
        // any Python runs -- is what makes a create command see the user's
        // selection: cmds.createNode RESELECTS the node it makes, so a read
        // after the fact would return the new node instead. Python splits on RS
        // and an instance command still takes only the first.
        std::string target;
        {
            MSelectionList objs;
            MStringArray names;
            if (argData.getObjects(objs) == MS::kSuccess &&
                objs.getSelectionStrings(names) == MS::kSuccess &&
                names.length() > 0) {
                for (unsigned _oi = 0; _oi < names.length(); ++_oi) {
                    if (_oi) target += "\x1e";
                    target += names[_oi].asChar();
                }
            }
        }
        MString out;
        st = mpycmd_spine::runDispatch("spineBuildSystem", "build_system", blob, target,
                                      true, out);
        if (!st) return st;
        mpycmd_spine::applyResult(this, out);
        return MS::kSuccess;
    }
};


