MStatus register_Spine(MFnPlugin& plugin) {
    using namespace nd_spine;
    MStatus _st = plugin.registerNode("spine", Spine::id, Spine::creator, Spine::initialize);
    if (!_st) return _st;
    MStatus _cs_SpineBuildSystemCmd = plugin.registerCommand("spineBuildSystem", SpineBuildSystemCmd::creator, SpineBuildSystemCmd::newSyntax); if (!_cs_SpineBuildSystemCmd) return _cs_SpineBuildSystemCmd;
    MStatus _cs_SpineResetRestCmd = plugin.registerCommand("spineResetRest", SpineResetRestCmd::creator, SpineResetRestCmd::newSyntax); if (!_cs_SpineResetRestCmd) return _cs_SpineResetRestCmd;
    MStatus _cs_SpineSetDriversCmd = plugin.registerCommand("spineSetDrivers", SpineSetDriversCmd::creator, SpineSetDriversCmd::newSyntax); if (!_cs_SpineSetDriversCmd) return _cs_SpineSetDriversCmd;
    MStatus _cs_SpineCmd = plugin.registerCommand("spine", SpineCmd::creator, SpineCmd::newSyntax); if (!_cs_SpineCmd) return _cs_SpineCmd;
    return _st;
}

MStatus deregister_Spine(MFnPlugin& plugin) {
    using namespace nd_spine;
    plugin.deregisterCommand("spineBuildSystem");
    plugin.deregisterCommand("spineResetRest");
    plugin.deregisterCommand("spineSetDrivers");
    plugin.deregisterCommand("spine");
    return plugin.deregisterNode(Spine::id);
}
